<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Mobile Premium Dark Hero</title>
    <style>
        :root {
            --bg-color: #0a0a0b;
            --text-primary: #ffffff;
            --text-secondary: #888888;
            --accent-red: #ff2d2d;
            --accent-red-gradient: linear-gradient(135deg, #ff4d4d 0%, #cc0000 100%);
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --font-mono: "SF Mono", Monaco, "Cascadia Code", "Roboto Mono", Consolas, monospace;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-primary);
            font-family: var(--font-sans);
            width: 390px; /* Fixed width for screenshot simulation */
            min-height: 100vh;
            overflow-x: hidden;
            position: relative;
            border-left: 1px solid #222;
            border-right: 1px solid #222;
            margin: 0 auto;
        }

        /* --- Header --- */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px 24px;
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 50;
        }

        .logo-area {
            display: flex;
            align-items: center;
            gap: 12px;
            font-family: var(--font-mono);
            font-size: 12px;
            letter-spacing: 1px;
            color: var(--text-secondary);
            text-transform: uppercase;
        }

        .logo-icon {
            width: 20px;
            height: 4px;
            background-color: var(--accent-red);
            position: relative;
        }

        .logo-icon::after {
            content: '';
            position: absolute;
            left: -6px;
            top: 0;
            width: 4px;
            height: 4px;
            background-color: var(--accent-red);
        }

        .nav-actions {
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .btn-dashboard {
            background: rgba(255, 255, 255, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.15);
            color: white;
            padding: 8px 16px;
            border-radius: 20px;
            font-size: 13px;
            font-weight: 500;
            text-decoration: none;
            backdrop-filter: blur(10px);
            transition: all 0.3s ease;
        }

        .menu-icon {
            width: 20px;
            height: 14px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            cursor: pointer;
        }

        .menu-line {
            width: 100%;
            height: 2px;
            background-color: white;
            border-radius: 2px;
        }

        /* --- Hero Section --- */
        .hero-section {
            padding-top: 80px;
            padding-bottom: 40px;
            display: flex;
            flex-direction: column;
            align-items: center;
            position: relative;
        }

        /* 3D Phone Mockup */
        .phone-container {
            width: 260px;
            height: 520px;
            perspective: 1000px;
            margin-bottom: 30px;
            position: relative;
            z-index: 10;
        }

        .phone-mockup {
            width: 100%;
            height: 100%;
            background: #111;
            border-radius: 36px;
            border: 8px solid #1a1a1a;
            box-shadow: 
                0 50px 100px -20px rgba(0,0,0,0.7),
                0 30px 60px -10px rgba(0,0,0,0.5),
                inset 0 0 0 2px #333,
                0 0 0 1px rgba(255,255,255,0.05);
            transform: rotateY(-10deg) rotateX(5deg) translateZ(0);
            transition: transform 0.5s cubic-bezier(0.23, 1, 0.32, 1);
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: flex-start;
            padding: 20px 16px;
        }

        .phone-screen-header {
            font-family: var(--font-mono);
            font-size: 9px;
            color: var(--accent-red);
            margin-bottom: 20px;
            opacity: 0.8;
            text-align: center;
            line-height: 1.4;
        }

        .waveform-container {
            width: 100%;
            height: 60px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 3px;
            margin-bottom: 25px;
        }

        .bar {
            width: 4px;
            background: linear-gradient(to top, #ff0000, #ff4444);
            border-radius: 2px;
            animation: wave 1.2s ease-in-out infinite;
        }

        @keyframes wave {
            0%, 100% { height: 20%; }
            50% { height: 90%; }
        }

        .stats-row {
            display: flex;
            gap: 18px;
            margin-bottom: 35px;
        }

        .stat-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 4px;
        }

        .stat-num {
            font-family: var(--font-mono);
            font-weight: bold;
            font-size: 18px;
            color: white;
        }

        .stat-label {
            font-family: var(--font-mono);
            font-size: 8px;
            color: #666;
            text-transform: uppercase;
        }

        .record-btn-wrapper {
            width: 56px;
            height: 56px;
            background: radial-gradient(circle at 30% 30%, #ff5555, #aa0000);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 10px 25px -5px rgba(255, 45, 45, 0.4);
            cursor: pointer;
            position: relative;
        }

        .mic-icon {
            width: 20px;
            height: 28px;
            background: white;
            clip-path: polygon(20% 0%, 80% 0%, 80% 60%, 100% 70%, 100% 100%, 0% 100%, 0% 70%, 20% 60%);
            border-radius: 10px 10px 0 0;
        }

        .phone-footer-text {
            position: absolute;
            bottom: 25px;
            font-family: var(--font-mono);
            font-size: 7px;
            color: #444;
            text-transform: uppercase;
            letter-spacing: 1px;
            text-align: center;
            width: 80%;
            line-height: 1.5;
        }

        /* Subtitle Text */
        .hero-subtitle {
            font-family: var(--font-mono);
            font-size: 11px;
            color: #666;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            text-align: center;
            max-width: 280px;
            line-height: 1.6;
            z-index: 10;
        }

        /* --- Marquee Strip --- */
        .marquee-container {
            width: 100%;
            background: #111;
            border-top: 1px solid #222;
            border-bottom: 1px solid #222;
            padding: 16px 0;
            margin-top: 40px;
            overflow: hidden;
            position: relative;
            z-index: 5;
        }

        .marquee-track {
            display: flex;
            gap: 48px;
            animation: scroll 20s linear infinite;
            width: max-content;
        }

        .marquee-item {
            font-family: var(--font-mono);
            font-size: 13px;
            color: #555;
            text-transform: uppercase;
            letter-spacing: 1px;
            white-space: nowrap;
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .marquee-item::before {
            content: '';
            width: 4px;
            height: 4px;
            background-color: var(--accent-red);
            border-radius: 50%;
            display: inline-block;
        }

        .marquee-item:first-child::before {
            display: none;
        }

        @keyframes scroll {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
        }

        /* --- Content Section (Below Fold) --- */
        .content-section {
            padding: 60px 24px;
        }

        .section-label {
            font-family: var(--font-mono);
            font-size: 11px;
            color: var(--accent-red);
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .label-line {
            width: 40px;
            height: 1px;
            background: #333;
        }

        h1 {
            font-size: 32px;
            line-height: 1.2;
            font-weight: 600;
            margin-bottom: 20px;
            letter-spacing: -0.5px;
        }

        p.desc {
            font-size: 16px;
            line-height: 1.6;
            color: #999;
            max-width: 320px;
        }

        .image-placeholder {
            width: 100%;
            height: 220px;
            background: #161618;
            border-radius: 16px;
            margin-top: 40px;
            position: relative;
            overflow: hidden;
        }

        .img-inner {
            width: 100%;
            height: 100%;
            background: linear-gradient(135deg, #1a1a1c 0%, #0f0f10 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: #333;
            font-family: var(--font-mono);
            font-size: 10px;
        }

        .nav-circle {
            position: absolute;
            bottom: 20px;
            left: 20px;
            width: 32px;
            height: 32px;
            background: black;
            border: 1px solid #333;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-family: serif;
            font-style: italic;
            font-size: 16px;
        }

    </style>
</head>
<body>

    <!-- Navigation -->
    <header>
        <div class="logo-area">
            <div class="logo-icon"></div>
            <span>Communication</span>
        </div>
        <div class="nav-actions">
            <a href="#" class="btn-dashboard">Open dashboard</a>
            <div class="menu-icon">
                <span class="menu-line"></span>
                <span class="menu-line"></span>
                <span class="menu-line"></span>
            </div>
        </div>
    </header>

    <!-- Main Hero -->
    <main class="hero-section">

        <!-- 3D Phone Mockup -->
        <div class="phone-container">
            <div class="phone-mockup">
                <div class="phone-screen-header">
                    September 26, June 19<br>
                    Walk, ethmoon instead
                </div>

                <div class="waveform-container" id="waveform">
                    <!-- JS will populate bars -->
                </div>

                <div class="stats-row">
                    <div class="stat-item">
                        <span class="stat-num">4</span>
                        <span class="stat-label">Mail</span>
                    </div>
                    <div class="stat-item">
                        <span class="stat-num">2</span>
                        <span class="stat-label">Skype</span>
                    </div>
                    <div class="stat-item">
                        <span class="stat-num">4</span>
                        <span class="stat-label">Call</span>
                    </div>
                    <div class="stat-item">
                        <span class="stat-num">5</span>
                        <span class="stat-label">Mail</span>
                    </div>
                </div>

                <div class="record-btn-wrapper">
                    <div class="mic-icon"></div>
                </div>

                <div class="phone-footer-text">
                    Product Process &nbsp;&nbsp;•&nbsp;&nbsp; Connects with the Live Dashboard
                </div>
            </div>
        </div>

        <p class="hero-subtitle">
            These counters are live. Zero until real work happens here.
        </p>

    </main>

    <!-- Marquee Strip -->
    <div class="marquee-container">
        <div class="marquee-track">
            <div class="marquee-item">Everything</div>
            <div class="marquee-item">Streaming Speech</div>
            <div class="marquee-item">Live Data</div>
            <div class="marquee-item">Real-time Sync</div>
            <div class="marquee-item">Everything</div>
            <div class="marquee-item">Streaming Speech</div>
            <div class="marquee-item">Live Data</div>
            <div class="marquee-item">Real-time Sync</div>
        </div>
    </div>

    <!-- Secondary Content Section -->
    <section class="content-section">
        <div class="section-label">
            01 <span class="label-line"></span> Who it serves
        </div>
        <h1>Built for teams that live on the phone.</h1>
        <p class="desc">
            Front desks, intake lines, order queues: the places where waiting costs money.
        </p>

        <div class="image-placeholder">
            <div class="img-inner">Interior / Environment Preview</div>
            <div class="nav-circle">N</div>
        </div>
    </section>

    <script>
        // Generate random waveform bars
        const waveformContainer = document.getElementById('waveform');
        const barCount = 30;

        for(let i=0; i<barCount; i++) {
            const bar = document.createElement('div');
            bar.className = 'bar';
            // Randomize animation delay for organic look
            bar.style.animationDelay = `${Math.random() * 1}s`;
            bar.style.height = `${Math.random() * 40 + 10}%`;
            waveformContainer.appendChild(bar);
        }
    </script>
</body>
</html>
```
